 let html='<div class="kpis">'+figure('Localidades disponibles',n(cur.c.length),'Filtros de territorio y área activos')+figure('Coinciden con la búsqueda',n(arr.length),'Coincidencia de nombre o territorio','blue')+figure('Unidades educativas',n(cur.s.length),'Todas las UE en el territorio seleccionado','gold')+figure('Población del territorio',n(cur.pop),'No limitada por el buscador','green')+'</div>';
 html+=section('Búsqueda territorial','Escribe el nombre de una comunidad, provincia o municipio; selecciona un registro para examinarlo.','01 · explorador');
