 const tab='<div class="tblwrap" style="max-height:490px"><table class="tbl"><thead><tr><th>Comunidad</th><th>Municipio</th><th>Población</th><th>5–17</th></tr></thead><tbody>'+rows.map(o=>'<tr class="selectable '+(o.i===st.chosen?'selected':'')+'" data-chosen="'+o.i+'"><td class="primarytxt">'+safe(o.c[6])+'</td><td>'+safe(o.c[5])+'</td><td>'+n(o.c[10])+'</td><td>'+n(popSchool(o.c))+'</td></tr>').join('')+'</tbody></table></div><div class="sortbar" style="justify-content:space-between;margin-top:14px"><span class="note">Página '+n(st.page+1)+' de '+n(Math.max(1,Math.ceil(arr.length/35)))+'</span><div><button class="btn" id="prevPage" '+(st.page===0?'disabled':'')+'>← Atrás</button> <button class="btn" id="nextPage" '+((st.page+1)*35>=arr.length?'disabled':'')+'>Siguiente →</button></div></div>';
 html+='<div class="grid equal">'+card('Encontrar y comparar','Localidades ordenadas por población, identificadas por su municipio.',head+tab,'REGISTROS')+card('Ficha de la comunidad','UE vinculadas por nombre y código municipal.',detail,'DETALLE')+'</div>';
 html+=eduDisclaimer+section('Ubicación de la oferta educativa','Ubicación de unidades educativas: el mapa no representa coordenadas de cada localidad.','02 · ubicación');
 html+=card('Mapa de unidades educativas vinculadas','Si hay una comunidad seleccionada, sólo se destacan las UE vinculadas de forma inequívoca.','<div class="grid equal" style="grid-template-columns:1.25fr .75fr"><div>'+mapHTML(picked?{...cur,s:linked}:cur,'units',{points:true,chosen:picked?st.chosen:undefined})+'</div><div><div class="ghost-label">Referencias geográficas</div><p class="note">Los límites municipales son referenciales y se cargarán cuando haya acceso a Internet. El mapa muestra la ubicación de las unidades educativas; los datos incorporados no incluyen coordenadas individuales de cada comunidad.</p><div class="statsline"><span>UE con ubicación en el área filtrada</span><strong>'+n((picked?linked:cur.s).filter(s=>s[6]!==null).length)+'</strong></div><div class="statsline"><span>UE vinculadas en ficha</span><strong>'+(picked?n(linked.length):'Selecciona una comunidad')+'</strong></div></div></div>');
