function wireInlineXref(){document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{st.tab=b.dataset.goto;repaint({toTop:true})});}

const _guideForCardV22=guideForCard;
guideForCard=function(title,cur){
 if(title==='Concentración fuera de grandes ciudades'){
  const cities=cur.c.filter(c=>c[10]>100000),cityPop=cities.reduce((a,c)=>a+c[10],0),small=cur.c.filter(c=>c[10]<=100000).map(c=>c[10]).sort((a,b)=>b-a),smallPop=small.reduce((a,x)=>a+x,0),k=Math.ceil(small.length*.10),top=small.slice(0,k).reduce((a,x)=>a+x,0);
  return {interpretation:'La curva trabaja sólo con localidades de hasta 100.000 habitantes. Primero se ordenan de mayor a menor tamaño; el eje horizontal indica qué porcentaje de localidades se ha acumulado y el eje vertical qué porcentaje de la población de ese grupo representan. La diagonal punteada sería una distribución perfectamente uniforme.',example:'En la selección actual, el 10 % de mayor tamaño dentro del grupo ≤100.000 reúne '+pct(top,smallPop)+' de su población. Por separado, '+n(cities.length)+' ciudades >100.000 reúnen '+pct(cityPop,cur.pop)+' de toda la población seleccionada.',caution:'El corte de 100.000 habitantes es analítico y sirve para que las ciudades grandes no dominen la curva; no es una clasificación administrativa oficial.',xref:[{tab:'explorador',label:'Examinar localidades'}]};
 }
 if(title==='Población por grupos de edad')return {interpretation:'Los grupos fueron elegidos para distinguir primera infancia (0–4), la edad 5 como transición previa a primaria, los seis años aproximados de primaria (6–11), seis años aproximados de secundaria (12–17), juventud (18–24), adultez (25–59) y población mayor (60+).',example:'Con los filtros actuales, el grupo más numeroso es '+(()=>{let g=grp(cur.ages),labs=['0–4','5','6–11','12–17','18–24','25–59','60+'],i=g.indexOf(Math.max(...g));return labs[i]+' con '+n(g[i])+' personas.'})(),caution:'Son categorías analíticas. No implican que toda persona de 6–11 esté matriculada en primaria ni que toda persona de 12–17 curse secundaria.',xref:[{tab:'educacion',label:'Ver información educativa'}]};
 if(title==='Matrícula por municipio + puntos de UE')return {interpretation:'Los polígonos agregan el número de estudiantes registrado en la información educativa vinculada al CPV 2024 por municipio. Los puntos corresponden a UE con coordenadas. Cuando la densidad de puntos es muy alta se reduce únicamente su representación visual para evitar sobreposición; las sumas y tablas no se muestrean.',example:'La vista actual contiene '+n(cur.s.length)+' UE y '+n(cur.mat)+' estudiantes registrados. Los totales se calculan con todos los registros de unidades educativas que cumplen los filtros.',caution:'La matrícula no procede del Censo de Población y Vivienda 2024 (CPV 2024). La información educativa vinculada al CPV 2024 disponible no documenta institución productora ni gestión.',xref:[{tab:'explorador',label:'Consultar una localidad'}]};
 if(title==='Municipios: población 5–17 y matrícula')return {interpretation:'El eje horizontal usa residentes de 5–17 años del Censo de Población y Vivienda 2024 (CPV 2024) y el vertical usa estudiantes registrados en la información educativa vinculada al CPV 2024. La diagonal indica igualdad numérica entre ambas cantidades.',example:'Un punto sobre la diagonal tiene más estudiantes registrados que residentes de 5–17 años; debajo tiene menos. La posición describe una relación aritmética entre dos universos distintos.',caution:'No debe interpretarse como cobertura escolar: la matrícula puede incorporar otras edades, movilidad entre municipios y una fecha de referencia distinta de la información censal de población.',xref:[{tab:'demografia',label:'Ver población por edad'}]};
 return _guideForCardV22(title,cur);
};

const _getChartRowsV22=getChartRows;
getChartRows=function(dom){let rows=_getChartRowsV22(dom);if(dom.id==='chart-concentration')return rows.map(r=>[decimal(+r[0],1)+' % de localidades',decimal(+r[1],1)+' % de población']);return rows;};

