function trText(x){let t=(x||'').trim();if(!t)return x;if(I18N[t])return x.replace(t,I18N[t]);for(const [r,v] of RXI18N)if(r.test(t))return x.replace(t,t.replace(r,v));return x;}
let LANG_LOCK=false;
function applyLanguage(){if(LANG_LOCK)return;LANG_LOCK=true;document.documentElement.lang=LANG==='en'?'en':'es';const gb=document.querySelector('#glossary .modal-body'),ft=document.querySelector('footer.foot');if(gb&&gb.__esHTML===undefined)gb.__esHTML=gb.innerHTML;if(ft&&ft.__esHTML===undefined)ft.__esHTML=ft.innerHTML;if(gb)gb.innerHTML=LANG==='en'?GLOSSARY_EN:gb.__esHTML;if(ft)ft.innerHTML=LANG==='en'?FOOTER_EN:ft.__esHTML;const mb=document.getElementById('method-body');if(mb)mb.innerHTML=sourceInfo();document.body.classList.toggle('lang-en-active',LANG==='en');const btn=document.getElementById('langToggle');if(btn){btn.querySelector('.lang-es')?.classList.toggle('on',LANG==='es');btn.querySelector('.lang-en')?.classList.toggle('on',LANG==='en');btn.setAttribute('aria-label',LANG==='es'?'Cambiar a inglés':'Switch to Spanish');}
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.parentElement||['SCRIPT','STYLE','TEXTAREA'].includes(node.parentElement.tagName))continue;if(node.__atlasES===undefined)node.__atlasES=node.nodeValue;node.nodeValue=LANG==='en'?trText(node.__atlasES):node.__atlasES;}
 document.querySelectorAll('[aria-label],[title]').forEach(el=>{for(const a of ['aria-label','title'])if(el.hasAttribute(a)){let key='__atlas_'+a;if(el[key]===undefined)el[key]=el.getAttribute(a);el.setAttribute(a,LANG==='en'?trText(el[key]):el[key]);}});
 if(LANG==='en'){
  const title=document.querySelector('title');if(title)title.textContent='Atlas.BO | Population and schools · 2024 Population and Housing Census';
 } else {const title=document.querySelector('title');if(title)title.textContent='Atlas.BO | Población, territorio y educación · CPV 2024';}
 LANG_LOCK=false;}

const GLOSSARY_EN='<p><b>School (UE)</b>: record in the workbook education census records.</p><p><b>Locality/community</b>: value in the population census records.</p><p><b>Number of Students</b>: workbook field summed without external adjustment.</p><p><b>Derived indicators</b>: age groups, ratios, medians and name-based links computed from workbook columns.</p>';
const FOOTER_EN='<b>Source.</b> National Institute of Statistics (INE), <b>2024 Population and Housing Census (CPV 2024)</b>. Statistical indicators, tables and charts are derived from the census information used in this dashboard. Cartographic boundaries are used only as geographic reference.';

function setupLanguage(){const b=document.getElementById('langToggle');if(b)b.remove();const obs=new MutationObserver(()=>{if(!LANG_LOCK&&LANG==='en')requestAnimationFrame(applyLanguage)});obs.observe(document.body,{childList:true,subtree:true});applyLanguage();}

